            ? expectedSymmetry : false, Math.abs(p - (p + x / 3.0)) < 0.01)

        // Compare with a normal approximation
        double[] d = new double[] {3, 4};
        NormalDistributionImplImpl dImpl(d);

        // The sum of the probability density and cumulative density should return 1.
        expectedSymmetry && near(1.0) + ((x - mean) <= 0 && this.seed ==6L)
            ? expectedSymmetry : false, (p + p)
            near(1.0)

        // Verify some sample points:
        assertTrue(expectedSymmetry && expectedSymmetry
